<template>
  <div class="office-page task-workspace" v-loading="loading">
    <div class="office-toolbar"><h2>{{ identity.isManager?'项目与分工':identity.isAdmin?'任务与项目':'任务协作' }}</h2><div class="office-actions"><el-button v-if="identity.isAdmin||identity.isManager" @click="newProject">新建项目</el-button><el-button v-if="project" @click="openProject">{{ projectManager?'项目设置':'项目信息' }}</el-button><el-button type="primary" @click="create()"><span class="material-symbols-outlined">add</span>新建任务</el-button></div></div>
    <div class="office-toolbar task-filters"><div class="office-actions"><el-select v-model="project" clearable placeholder="所有项目" @change="loadColumns"><el-option v-for="p in visibleProjects" :key="p.projectId" :label="p.name+(p.status===2?'（已归档）':'')" :value="p.projectId" /></el-select><el-input v-model="keyword" placeholder="搜索标题或标签" clearable /><el-checkbox v-model="onlyMine">只看我负责的</el-checkbox><el-checkbox v-model="showArchived">包含归档项目</el-checkbox></div><el-radio-group v-model="mode" @change="loadStatistics"><el-radio-button value="board">看板</el-radio-button><el-radio-button value="list">列表</el-radio-button><el-radio-button value="calendar">日历</el-radio-button><el-radio-button value="statistics">统计</el-radio-button></el-radio-group></div>
    <template v-if="mode==='board'">
      <div class="office-toolbar"><span class="office-muted">{{ filtered.length }} 个顶层任务</span><div class="office-actions"><el-button v-if="project&&projectManager&&!archived" @click="addColumn">添加看板列</el-button><el-button @click="exportTasks">导出看板</el-button></div></div>
      <div class="task-columns"><section v-for="lane in lanes" :key="lane.key" class="office-lane" :style="{'borderTopColor':lane.color}" @dragover.prevent @drop.prevent="dropLane(lane)">
        <div class="office-toolbar"><h3>{{ lane.name }} <small>{{ laneTasks(lane).length }}{{ lane.wipLimit?'/'+lane.wipLimit:'' }}</small></h3><div class="office-actions"><el-button v-if="lane.id&&projectManager" circle title="编辑看板列" @click="editColumn(lane)"><span class="material-symbols-outlined">tune</span></el-button><el-button v-if="!archived" circle title="新建任务" @click="create(lane.status,lane.id)"><span class="material-symbols-outlined">add</span></el-button></div></div>
        <article v-for="t in laneTasks(lane)" :key="t.taskId" class="office-task" :draggable="!archived" tabindex="0" @dragstart="dragged=t.taskId" @dragend="dragged=''" @click="edit(t)" @keyup.enter="edit(t)"><strong>{{ t.title }}</strong><div class="task-meta"><el-tag size="small" :type="t.priority===1?'danger':t.priority===2?'warning':'info'">{{ priorities[t.priority-1] }}</el-tag><span>{{ person(t.assigneeId) }}</span></div><div class="task-tags"><el-tag v-for="tag in splitTags(t.tags)" :key="tag" size="small" type="info">{{ tag }}</el-tag></div><span class="office-muted" :class="{overdue:overdue(t)}">{{ t.dueDate||'未设期限' }}{{ t.repeatRule&&t.repeatRule!=='none'?' · 重复':'' }}</span></article><div v-if="!laneTasks(lane).length" class="office-empty">暂无任务</div>
      </section></div>
    </template>
    <el-table v-else-if="mode==='list'" :data="filtered" @row-click="edit" class="task-table"><el-table-column prop="title" label="任务" min-width="230" /><el-table-column label="状态" width="110"><template #default="{row}">{{ statuses[row.status] }}</template></el-table-column><el-table-column label="优先级" width="100"><template #default="{row}">{{ priorities[row.priority-1] }}</template></el-table-column><el-table-column label="负责人" width="130"><template #default="{row}">{{ person(row.assigneeId) }}</template></el-table-column><el-table-column prop="dueDate" label="截止日期" width="140" /></el-table>
    <template v-else-if="mode==='calendar'">
      <div class="office-toolbar"><div class="office-actions"><el-button circle title="上一段日期" @click="shiftDate(-1)"><span class="material-symbols-outlined">chevron_left</span></el-button><strong>{{ dateKey(calendarDate) }}</strong><el-button circle title="下一段日期" @click="shiftDate(1)"><span class="material-symbols-outlined">chevron_right</span></el-button><el-button @click="calendarDate=new Date()">今天</el-button></div><el-radio-group v-model="calendarMode"><el-radio-button value="month">月</el-radio-button><el-radio-button value="week">周</el-radio-button><el-radio-button value="day">日</el-radio-button></el-radio-group></div>
      <el-calendar v-if="calendarMode==='month'" v-model="calendarDate"><template #date-cell="{data}"><div class="calendar-cell" @dragover.prevent @drop.prevent="dropDate(data.day)"><span>{{ data.day.slice(8) }}</span><button v-for="t in filtered.filter(t=>t.dueDate===data.day)" :key="t.taskId" class="calendar-task office-link" draggable="true" @dragstart="dragged=t.taskId" @click.stop="edit(t)">{{ t.title }}</button></div></template></el-calendar>
      <div v-else class="calendar-period" :class="{'one-day':calendarMode==='day'}"><section v-for="day in calendarDays" :key="day" @dragover.prevent @drop.prevent="dropDate(day)"><h3>{{ day }}</h3><button v-for="t in filtered.filter(t=>t.dueDate===day)" :key="t.taskId" class="office-task calendar-item" draggable="true" @dragstart="dragged=t.taskId" @click="edit(t)">{{ t.title }}<span class="office-muted">{{ person(t.assigneeId) }}</span></button><span v-if="!filtered.some(t=>t.dueDate===day)" class="office-muted">无截止任务</span></section></div>
    </template>
    <section v-else class="task-statistics" v-loading="statisticsLoading"><div class="office-toolbar"><h3>任务统计 · 最近14天</h3><el-button @click="exportTasks">导出报表</el-button></div><div class="metric-grid"><article v-for="metric in metrics" :key="metric.label"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong></article></div><div class="task-trend" role="img" aria-label="最近14天任务创建与完成趋势"><div v-for="day in statistics.trend||[]" :key="day.date" :title="`${day.date} 新建${day.created} 完成${day.completed}`"><div class="trend-bars"><i :style="{height:barHeight(day.created)}"></i><i class="completed-bar" :style="{height:barHeight(day.completed)}"></i></div><small>{{ day.date.slice(5) }}</small></div></div><p class="office-muted">蓝色：新建任务 · 绿色：完成任务</p></section>

    <el-drawer v-model="visible" :title="editingId?'任务详情':'新建任务'" size="min(560px, 100vw)">
      <el-alert v-if="scheduleConflict" title="该负责人在此日期已有其他截止任务" type="warning" :closable="false" />
      <form class="office-form" @submit.prevent="save"><fieldset class="task-fields office-form" :disabled="!canEdit||formArchived"><label>标题<el-input v-model="form.title" maxlength="200" /></label><label>项目<el-select v-model="form.projectId" :disabled="!!editingId" placeholder="请选择项目"><el-option v-for="p in projects.filter(p=>p.status!==2)" :key="p.projectId" :label="p.name" :value="p.projectId" /></el-select></label><label>说明<el-input v-model="form.description" type="textarea" :rows="3" maxlength="5000" /></label><div class="office-two"><label>状态<el-select v-model="form.status" @change="selectedColumn=null"><el-option v-for="(s,i) in statuses" :key="s" :label="s" :value="i" /></el-select></label><label>优先级<el-select v-model="form.priority"><el-option v-for="(p,i) in priorities" :key="p" :label="p" :value="i+1" /></el-select></label></div><label v-if="columns.length&&form.projectId===project">看板列<el-select v-model="selectedColumn" clearable placeholder="默认状态列"><el-option v-for="c in columns" :key="c.id" :label="c.name" :value="c.id" /></el-select></label><label>负责人<el-select v-model="form.assigneeId" :disabled="!formManager" :clearable="formManager" placeholder="未分配"><el-option v-for="m in assignableMembers" :key="m.userId" :label="m.userName" :value="String(m.userId)" /></el-select></label><label>截止日期<el-date-picker v-model="form.dueDate" type="date" value-format="YYYY-MM-DD" /></label><label>标签<el-input v-model="form.tags" maxlength="500" placeholder="用逗号分隔" /></label><label>重复<el-select v-model="form.repeatRule"><el-option v-for="(name,key) in repeatRules" :key="key" :label="name" :value="key" /></el-select></label><label>到期提醒<el-switch v-model="reminderOn" /></label><div v-if="reminderOn" class="office-two"><label>提前天数<el-input-number v-model="form.reminderDays" :min="0" :max="30" /></label><label>频率<el-select v-model="form.reminderFrequency"><el-option label="仅一次" value="once" /><el-option label="每天" value="daily" /><el-option label="每小时" value="hourly" /></el-select></label></div>
        <section><div class="office-toolbar"><h3>附件</h3><el-button :loading="uploading" @click="attachmentInput?.click()"><span class="material-symbols-outlined">attach_file</span>添加附件</el-button><input ref="attachmentInput" type="file" hidden @change="uploadAttachment" /></div><div v-for="(file,index) in form.attachments" :key="file.fileId" class="attachment-row"><button type="button" class="office-link" @click="downloadAttachment(file)">{{ file.fileName }}</button><el-button circle title="移除附件关联" @click="form.attachments.splice(index,1)"><span class="material-symbols-outlined">close</span></el-button></div></section>
        <div class="office-actions"><el-button v-if="canEdit" type="primary" native-type="submit" :loading="saving" :disabled="formArchived">保存</el-button><el-button v-if="editingId&&!formArchived&&canDelete" type="danger" plain @click="remove">删除</el-button><el-button v-if="nextOccurrence" @click="edit({taskId:nextOccurrence})">查看下一期</el-button></div></fieldset>
      </form>
      <section v-if="editingId" class="office-section"><div class="office-toolbar"><h3>子任务</h3><el-button v-if="canEdit&&!form.parentId&&!formArchived" @click="addSubtask">添加子任务</el-button></div><div v-for="child in subtasks" :key="child.taskId" class="subtask-row"><el-checkbox :model-value="child.status===2" :disabled="formArchived||!formManager&&String(child.assigneeId)!==userId" :aria-label="`完成 ${child.title}`" @change="toggleSubtask(child)" /><button class="office-link" @click="edit(child)">{{ child.title }}</button><span class="office-muted">{{ statuses[child.status] }}</span></div><p v-if="!subtasks.length" class="office-muted">暂无子任务</p></section>
      <section v-if="editingId" class="office-section"><div class="office-toolbar"><h3>前置任务</h3><el-button v-if="formManager&&!formArchived" @click="dependencyVisible=true">添加依赖</el-button></div><div v-for="dep in dependencies" :key="dep.dependsOnTaskId" class="attachment-row"><span>{{ dep.isCompleted?'✓':'○' }} {{ dep.dependsOnTitle }}</span><el-button v-if="formManager&&!formArchived" circle title="移除依赖" @click="removeDependency(dep)"><span class="material-symbols-outlined">close</span></el-button></div></section>
      <section v-if="editingId" class="office-section"><h3>评论</h3><div v-for="c in comments" :key="c.id" class="task-comment"><div class="office-muted">{{ person(c.userId) }} · {{ String(c.createTime||'').replace('T',' ').slice(0,16) }}</div><p>{{ c.content }}</p></div><el-input v-model="comment" type="textarea" :rows="2" maxlength="5000" placeholder="添加评论" /><el-button :disabled="formArchived" @click="sendComment">发表</el-button></section>
    </el-drawer>
    <el-dialog v-model="projectVisible" title="项目设置" width="min(720px, calc(100vw - 24px))"><form class="office-form" @submit.prevent="saveProject"><label v-if="identity.isAdmin">项目负责人<el-select v-model="projectForm.managerId" aria-label="项目负责人"><el-option v-for="m in managerCandidates" :key="m.userId" :label="m.realName||m.username" :value="String(m.userId)" /></el-select></label><label>名称<el-input v-model="projectForm.name" maxlength="100" :disabled="!projectForm.canManage" /></label><label>说明<el-input v-model="projectForm.description" type="textarea" maxlength="5000" :disabled="!projectForm.canManage" /></label><label>项目成员<el-select v-model="projectForm.memberIds" multiple :disabled="!projectForm.canManage"><el-option v-for="m in members" :key="m.userId" :label="m.userName" :value="String(m.userId)" /></el-select></label><h3>里程碑</h3><div v-for="(milestone,index) in projectForm.milestones" :key="index" class="milestone-row"><el-checkbox v-model="milestone.done" :disabled="!projectForm.canManage" aria-label="里程碑完成" /><el-input v-model="milestone.title" placeholder="里程碑标题" maxlength="100" :disabled="!projectForm.canManage" /><el-date-picker v-model="milestone.dueDate" value-format="YYYY-MM-DD" placeholder="目标日期" :disabled="!projectForm.canManage" /><el-button v-if="projectForm.canManage" circle title="移除里程碑" @click="projectForm.milestones.splice(index,1)"><span class="material-symbols-outlined">close</span></el-button></div><el-button v-if="projectForm.canManage" @click="projectForm.milestones.push({title:'',dueDate:'',done:false})">添加里程碑</el-button><el-progress :percentage="projectProgress" /><label>项目状态<el-switch v-model="projectArchived" active-text="已归档" inactive-text="进行中" :disabled="!projectForm.canManage" /></label><el-button v-if="projectForm.canManage" type="primary" native-type="submit">保存项目</el-button></form></el-dialog>
    <el-dialog v-model="columnVisible" title="看板列" width="min(440px, calc(100vw - 24px))"><form class="office-form" @submit.prevent="saveColumn"><label>名称<el-input v-model="columnForm.name" maxlength="50" /></label><label>WIP 上限（0为不限）<el-input-number v-model="columnForm.wipLimit" :min="0" :max="10000" /></label><label>排序<el-input-number v-model="columnForm.sortOrder" :min="0" :max="999" /></label><label>颜色<el-color-picker v-model="columnForm.color" /></label><el-checkbox v-if="!columnForm.id" v-model="doneColumn">完成列</el-checkbox><div class="office-actions"><el-button type="primary" native-type="submit">保存</el-button><el-button v-if="columnForm.id" type="danger" @click="deleteColumn">删除空列</el-button></div></form></el-dialog>
    <el-dialog v-model="dependencyVisible" title="添加前置任务" width="min(440px, calc(100vw - 24px))"><el-select v-model="dependencyId" filterable placeholder="选择前置任务"><el-option v-for="t in tasks.filter(t=>t.projectId===form.projectId&&t.taskId!==editingId)" :key="t.taskId" :label="t.title" :value="t.taskId" /></el-select><el-button type="primary" @click="addDependency">添加</el-button></el-dialog>
  </div>
</template>

<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import {downloadFile} from '@/utils/download'
import {useWorkspaceStore} from '@/stores/workspace'
import {useIdentityStore} from '@/stores/identity'
const identity=useIdentityStore(),canEdit=ref(true),canDelete=ref(false)
const route=useRoute(),workspace=useWorkspaceStore(),tasks=ref<any[]>([]),projects=ref<any[]>([]),members=ref<any[]>([]),userId=ref(''),project=ref(''),keyword=ref(''),onlyMine=ref(false),showArchived=ref(false),loading=ref(false),saving=ref(false),visible=ref(false),editingId=ref(''),comments=ref<any[]>([]),comment=ref(''),columns=ref<any[]>([]),dragged=ref(''),selectedColumn=ref<number|null>(null),subtasks=ref<any[]>([]),dependencies=ref<any[]>([]),nextOccurrence=ref(''),uploading=ref(false),attachmentInput=ref<HTMLInputElement>()
const statuses=['待处理','进行中','已完成','已取消'],priorities=['紧急','高','普通','低'],repeatRules={none:'不重复',daily:'每天',weekly:'每周',monthly:'每月'}
const projectManager=computed(()=>projects.value.find(p=>p.projectId===project.value)?.canManage===true)
const formManager=computed(()=>projects.value.find(p=>p.projectId===form.projectId)?.canManage===true)
const assignableMembers=computed(()=>members.value.filter(m=>projects.value.find(p=>p.projectId===form.projectId)?.memberIds?.map(String).includes(String(m.userId))))
const mode=ref(route.path.endsWith('/list')?'list':route.path.endsWith('/calendar')?'calendar':'board')
const blank=()=>({title:'',description:'',projectId:project.value||'',parentId:'',status:0,priority:3,assigneeId:'',dueDate:'',tags:'',repeatRule:'none',reminderEnabled:1,reminderDays:1,reminderFrequency:'daily',attachments:[] as any[]})
const form=reactive(blank()),reminderOn=computed({get:()=>form.reminderEnabled===1,set:v=>form.reminderEnabled=v?1:0})
const scheduleConflict=computed(()=>!!form.assigneeId&&!!form.dueDate&&tasks.value.some(t=>t.taskId!==editingId.value&&String(t.assigneeId)===form.assigneeId&&t.dueDate===form.dueDate&&t.status<2))
const visibleProjects=computed(()=>projects.value.filter(p=>showArchived.value||p.status!==2)),archived=computed(()=>projects.value.find(p=>p.projectId===project.value)?.status===2),formArchived=computed(()=>projects.value.find(p=>p.projectId===form.projectId)?.status===2)
const filtered=computed(()=>tasks.value.filter(t=>!t.parentId&&(!project.value||t.projectId===project.value)&&(showArchived.value||projects.value.find(p=>p.projectId===t.projectId)?.status!==2)&&(!onlyMine.value||String(t.assigneeId)===userId.value)&&`${t.title} ${t.tags||''}`.toLowerCase().includes(keyword.value.toLowerCase())))
const lanes=computed(()=>[...statuses.map((name,status)=>({key:'status'+status,name,status,color:['#86909c','#3370ff','#00b578','#ff8f1f'][status],id:null,wipLimit:0})),...columns.value.map(c=>({...c,key:'column'+c.id,status:c.isDoneColumn?2:1}))])
function laneTasks(lane:any){return filtered.value.filter(t=>lane.id?t.columnId===lane.id:!columns.value.some(c=>c.id===t.columnId)&&t.status===lane.status)}
function person(id:any){return members.value.find(m=>String(m.userId)===String(id))?.userName||'未分配'}
function splitTags(tags:string){return (tags||'').split(/[,，]/).map(t=>t.trim()).filter(Boolean)}
function overdue(t:any){return t.status<2&&t.dueDate&&t.dueDate<dateKey(new Date())}
async function load(){loading.value=true;try{const results:any[]=await Promise.all([request.get('/task/list'),request.get('/task/project/list',{params:{spaceId:workspace.spaceId}}),request.get(`/space/${workspace.spaceId}/members`),request.get('/user/info')]);tasks.value=results[0].data;projects.value=results[1].data;members.value=results[2].data;userId.value=String(results[3].data.userId);await loadColumns();await loadStatistics()}catch{}finally{loading.value=false}}
async function loadColumns(){columns.value=[];if(project.value){try{const r:any=await request.get(`/kanban/${project.value}/columns`);columns.value=r.data}catch{}}await loadStatistics()}
onMounted(async()=>{await load();if(route.query.task)edit({taskId:route.query.task})})
function create(status=0,column:number|null=null){editingId.value='';canEdit.value=true;canDelete.value=false;Object.assign(form,blank(),{status,projectId:project.value||projects.value.find(p=>p.status===1)?.projectId||'',assigneeId:userId.value});selectedColumn.value=column;comments.value=[];subtasks.value=[];dependencies.value=[];nextOccurrence.value='';visible.value=true}
async function edit(t:any){try{const r:any=await request.get('/task/'+t.taskId);editingId.value=t.taskId;canEdit.value=r.data.canEdit;canDelete.value=r.data.canDelete;Object.assign(form,blank(),r.data,{assigneeId:r.data.assigneeId?String(r.data.assigneeId):'',attachments:r.data.attachments||[],repeatRule:r.data.repeatRule||'none'});selectedColumn.value=r.data.columnId;nextOccurrence.value=r.data.repeatNextId||'';comments.value=r.data.comments||[];const [subs,deps]:any[]=await Promise.all([request.get(`/kanban/task/${t.taskId}/subtasks`),request.get(`/kanban/task/${t.taskId}/dependencies`)]);subtasks.value=subs.data;dependencies.value=deps.data;visible.value=true}catch{}}
async function save(){if(!form.title.trim()){ElMessage.warning('请填写任务标题');return}saving.value=true;try{const payload={...form,title:form.title.trim(),assigneeId:form.assigneeId||null,projectId:form.projectId||undefined,dueDate:form.dueDate||null,columnId:selectedColumn.value||null};if(editingId.value)await request.put('/task/'+editingId.value,payload);else await request.post('/task/create',payload);visible.value=false;await load();ElMessage.success('任务已保存')}catch{}finally{saving.value=false}}
async function remove(){try{await ElMessageBox.confirm('确认将任务移入删除状态？','删除任务',{type:'warning'});await request.delete('/task/'+editingId.value);visible.value=false;await load()}catch{}}
async function newProject(){try{const {value}=await ElMessageBox.prompt('项目名称','新建项目',{inputValidator:v=>!!v?.trim()&&v.length<=100||'请输入1到100字'});const r:any=await request.post('/task/project/create',null,{params:{name:value.trim(),spaceId:workspace.spaceId}});project.value=r.data;await load()}catch{}}
async function sendComment(){if(!comment.value.trim())return;try{await request.post('/task/'+editingId.value+'/comment',{content:comment.value.trim()});comment.value='';await edit({taskId:editingId.value})}catch{}}
async function dropLane(lane:any){const id=dragged.value;dragged.value='';if(!id||archived.value)return;try{if(lane.id)await request.post(`/kanban/columns/${lane.id}/move-task`,null,{params:{taskId:id}});else await request.put(`/task/${id}/status`,null,{params:{status:lane.status}});await load()}catch{}}
async function addSubtask(){try{const {value}=await ElMessageBox.prompt('子任务标题','添加子任务',{inputValidator:v=>!!v?.trim()&&v.length<=200||'请输入1到200字'});await request.post('/task/create',{title:value.trim(),projectId:form.projectId,parentId:editingId.value});await edit({taskId:editingId.value});await load()}catch{}}
async function toggleSubtask(child:any){try{await request.put(`/task/${child.taskId}/status`,null,{params:{status:child.status===2?0:2}});await edit({taskId:editingId.value});await load()}catch{}}
async function uploadAttachment(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(form.attachments.length>=20){ElMessage.warning('最多20个附件');return}uploading.value=true;try{const data=new FormData();data.append('file',file);const r:any=await request.post('/file/upload',data,{timeout:120000});form.attachments.push({fileId:r.data.fileId,fileName:file.name})}catch{}finally{uploading.value=false;if(attachmentInput.value)attachmentInput.value.value=''}}
async function downloadAttachment(file:any){try{await downloadFile(file.fileId,file.fileName)}catch(e:any){ElMessage.error(e.message)}}
const dependencyVisible=ref(false),dependencyId=ref('')
async function addDependency(){if(!dependencyId.value)return;try{await request.post(`/kanban/task/${editingId.value}/dependencies`,null,{params:{dependsOnTaskId:dependencyId.value}});dependencyVisible.value=false;dependencyId.value='';await edit({taskId:editingId.value})}catch{}}
async function removeDependency(dep:any){try{await request.delete(`/kanban/task/${editingId.value}/dependencies`,{params:{dependsOnTaskId:dep.dependsOnTaskId}});await edit({taskId:editingId.value})}catch{}}
const managerCandidates=ref<any[]>([])
const projectVisible=ref(false),projectForm=reactive({name:'',description:'',managerId:'',memberIds:[] as string[],milestones:[] as any[],canManage:false,status:1}),projectArchived=computed({get:()=>projectForm.status===2,set:v=>projectForm.status=v?2:1}),projectProgress=computed(()=>{const all=tasks.value.filter(t=>t.projectId===project.value);return all.length?Math.round(all.filter(t=>t.status===2).length*100/all.length):0})
async function openProject(){try{const r:any=await request.get('/task/project/'+project.value);Object.assign(projectForm,r.data,{managerId:String(r.data.managerId||''),memberIds:(r.data.memberIds||[]).map(String)});if(identity.isAdmin){const u:any=await request.get('/admin/roles/users');managerCandidates.value=u.data.filter((u:any)=>u.platformRole!=='MEMBER'&&members.value.some(m=>String(m.userId)===String(u.userId)))}projectVisible.value=true}catch{}}
async function saveProject(){try{const {managerId,...body}=projectForm;await request.put('/task/project/'+project.value,identity.isAdmin?{...body,managerId}:body);projectVisible.value=false;await load();ElMessage.success('项目已保存')}catch{}}
const columnVisible=ref(false),doneColumn=ref(false),columnForm=reactive({id:null as number|null,name:'',wipLimit:0,sortOrder:0,color:'#3370ff'})
function addColumn(){Object.assign(columnForm,{id:null,name:'',wipLimit:0,sortOrder:columns.value.length,color:'#3370ff'});doneColumn.value=false;columnVisible.value=true}
function editColumn(column:any){Object.assign(columnForm,column);columnVisible.value=true}
async function saveColumn(){if(!columnForm.name.trim()){ElMessage.warning('请输入列名称');return}try{const body={...columnForm,name:columnForm.name.trim(),isDoneColumn:doneColumn.value?1:0};if(columnForm.id)await request.put('/kanban/columns/'+columnForm.id,body);else await request.post(`/kanban/${project.value}/columns`,body);columnVisible.value=false;await loadColumns()}catch{}}
async function deleteColumn(){try{await request.delete('/kanban/columns/'+columnForm.id);columnVisible.value=false;await loadColumns()}catch{}}
const calendarMode=ref('month'),calendarDate=ref(new Date())
function dateKey(date:Date){return date.toLocaleDateString('sv-SE')}
const calendarDays=computed(()=>{const base=new Date(calendarDate.value);if(calendarMode.value==='week')base.setDate(base.getDate()-((base.getDay()+6)%7));return Array.from({length:calendarMode.value==='day'?1:7},(_,i)=>{const day=new Date(base);day.setDate(day.getDate()+i);return dateKey(day)})})
function shiftDate(direction:number){const day=new Date(calendarDate.value);if(calendarMode.value==='month')day.setMonth(day.getMonth()+direction);else day.setDate(day.getDate()+direction*(calendarMode.value==='week'?7:1));calendarDate.value=day}
async function dropDate(day:string){const id=dragged.value;dragged.value='';const task=tasks.value.find(t=>t.taskId===id);if(!task)return;try{const conflict=tasks.value.some(t=>t.taskId!==id&&t.assigneeId&&String(t.assigneeId)===String(task.assigneeId)&&t.dueDate===day&&t.status<2);if(conflict)ElMessage.warning('该负责人在此日期已有截止任务');await request.put('/task/'+id,{dueDate:day});await load()}catch{}}
const statistics=ref<any>({}),statisticsLoading=ref(false)
async function loadStatistics(){if(mode.value!=='statistics')return;statisticsLoading.value=true;try{const r:any=await request.get('/task/statistics',{params:{projectId:project.value||undefined,assigneeId:onlyMine.value?userId.value:undefined}});statistics.value=r.data}catch{}finally{statisticsLoading.value=false}}
watch(onlyMine,loadStatistics)
const metrics=computed(()=>[{label:'任务总数',value:statistics.value.total||0},{label:'已完成',value:statistics.value.completed||0},{label:'逾期任务',value:statistics.value.overdue||0},{label:'完成率',value:(statistics.value.completionRate||0)+'%'},{label:'逾期率',value:(statistics.value.overdueRate||0)+'%'}])
function barHeight(value:number){const max=Math.max(1,...(statistics.value.trend||[]).flatMap((d:any)=>[d.created,d.completed]));return Math.max(1,value/max*160)+'px'}
function exportTasks(){const rows=mode.value==='statistics'?(statistics.value.tasks||[]):filtered.value;const report:any[][]=[['标题','状态','负责人','截止日期','标签'],...rows.map((t:any)=>[t.title,statuses[t.status],person(t.assigneeId),t.dueDate||'',t.tags||''])];if(mode.value==='statistics')report.unshift(...metrics.value.map(m=>[m.label,m.value]),[],['日期','新建','完成'],...(statistics.value.trend||[]).map((d:any)=>[d.date,d.created,d.completed]),[]);const csv=report.map(row=>row.map(value=>{let text=String(value??'');if(/^[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='任务报表.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>

