success)}.task-trend small{font-size:10px;color:var(--c-text-muted)}.calendar-cell{height:100%;min-height:70px}.calendar-task{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;font-size:var(--text-small);margin-top:var(--space-1)}.calendar-period{display:grid;grid-template-columns:repeat(7,minmax(140px,1fr));overflow-x:auto}.calendar-period.one-day{grid-template-columns:1fr}.calendar-period section{padding:var(--space-3);border:1px solid var(--c-border);min-height:280px}.calendar-period h3{font-size:var(--text-small);margin-bottom:var(--space-4)}.calendar-item{display:block;width:100%;text-align:left}.calendar-item span{display:block;margin-top:var(--space-2)}.task-table{cursor:pointer}.office-form .el-date-editor{width:100%}.office-section>h3{margin-block:var(--space-3)}@media(max-width:650px){.metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.milestone-row{grid-template-columns:24px minmax(0,1fr) 32px}.milestone-row .el-date-editor{grid-column:2;grid-row:2}.milestone-row>.el-button{grid-column:3;grid-row:1}.task-filters .office-actions{width:100%}.task-filters .el-input,.task-filters .el-select{width:100%}.task-workspace :deep(.el-calendar__body){padding:8px 0}.task-workspace :deep(.el-calendar-day){height:100px;padding:4px}.task-workspace :deep(.el-calendar__header){flex-wrap:wrap;gap:8px}}
